B.a0I=new A.c5("Volc\xe1n de Pacaya",14.382,-90.601,2552,"Escuintla",!0,"Muy visitado y accesible. Lleva agua y zapatos c\xf3modos; revisa la actividad antes de subir.","Very popular and accessible. Bring water and comfy shoes; check activity before hiking.","https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Pacaya-08.jpg/330px-Pacaya-08.jpg","Es uno de los pocos volcanes donde puedes acercarte a la lava; algunos hasta asan malvaviscos con su calor.")
B.a0y=new A.c5("Volc\xe1n de Fuego",14.473,-90.88,3763,"Chimaltenango",!0,"Activo y peligroso: NO se sube. Se observa desde el Acatenango con gu\xeda.","Active and dangerous: do NOT climb. Watch it from Acatenango with a guide.","https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Volc%C3%A1n_de_Fuego_-_Guatemala.jpg/330px-Volc%C3%A1n_de_Fuego_-_Guatemala.jpg","Es uno de los volcanes m\xe1s activos de Am\xe9rica; su erupci\xf3n de 2018 fue tr\xe1gica.")
B.a0z=new A.c5("Volc\xe1n Acatenango",14.501,-90.876,3976,"Chimaltenango",!1,"Caminata de 1-2 d\xedas con gu\xeda. Hace mucho fr\xedo de noche; lleva abrigo.","1-2 day hike with a guide. Very cold at night; bring warm clothes.","https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Guatemala_Volcano_Fuego.jpg/330px-Guatemala_Volcano_Fuego.jpg","De noche se ve al vecino Fuego hacer erupci\xf3n; por eso su campamento es tan famoso.")
B.a0x=new A.c5("Volc\xe1n de Agua",14.465,-90.743,3760,"Sacatep\xe9quez",!1,"Vistas a Antigua. Sube con gu\xeda y empieza temprano.","Views over Antigua. Hike with a guide and start early.","https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/Agua_Volcano_in_Antigua_Guatemala.jpg/330px-Agua_Volcano_in_Antigua_Guatemala.jpg","Domina el paisaje de Antigua; en 1541 una avalancha de agua y lodo destruy\xf3 la antigua capital.")
B.a0B=new A.c5("Volc\xe1n Atitl\xe1n",14.583,-91.186,3535,"Solol\xe1",!1,"Junto al lago de Atitl\xe1n. Caminata exigente; contrata gu\xeda local.",null,u.m,null)
B.a0H=new A.c5("Volc\xe1n San Pedro",14.655,-91.27,3020,"Solol\xe1",!1,"Tiene parque y sendero marcado. Buen mirador del lago.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Atitlan-Volcan-San-Pedro.jpg/500px-Atitlan-Volcan-San-Pedro.jpg",null)
B.a0n=new A.c5("Volc\xe1n Tolim\xe1n",14.612,-91.189,3158,"Solol\xe1",!1,"Menos visitado; sendero dif\xedcil. Ve con gu\xeda.",null,u.m,null)
B.a0C=new A.c5("Volc\xe1n Santa Mar\xeda",14.756,-91.552,3772,"Quetzaltenango",!0,"Cerca de Xela. Desde la cima se ve el domo activo Santiaguito.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/VolcanSantaMaria03.jpg/330px-VolcanSantaMaria03.jpg",null)
B.a0G=new A.c5("Volc\xe1n Tajumulco",15.043,-91.903,4220,"San Marcos",!1,"El punto m\xe1s alto de Centroam\xe9rica. Mucho fr\xedo; aclim\xe1tate a la altura.","The highest point in Central America. Very cold; acclimatize to the altitude.","https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Finca_Piamonte%2C_San_Rafael_Pie_de_la_Cuesta_01.JPG/330px-Finca_Piamonte%2C_San_Rafael_Pie_de_la_Cuesta_01.JPG","Con 4,220 m es el punto m\xe1s alto de toda Centroam\xe9rica.")
B.a0s=new A.c5("Volc\xe1n Tacan\xe1",15.132,-92.109,4060,"San Marcos",!0,"En la frontera con M\xe9xico. Caminata larga; planifica con gu\xeda.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Volcan_Tacana_01.jpg/330px-Volcan_Tacana_01.jpg",null)
B.a0v=new A.c5("Volc\xe1n Santiaguito",14.7419,-91.569,2550,"Quetzaltenango",!0,"Domo activo a los pies del Santa Mar\xeda. Obs\xe9rvalo de lejos: es peligroso.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Hot_lahar_at_Santiaguito_02.jpg/500px-Hot_lahar_at_Santiaguito_02.jpg",null)
B.a0w=new A.c5("Volc\xe1n Chicabal",14.7884,-91.656,2900,"Quetzaltenango",!1,"Tiene una laguna sagrada en el cr\xe1ter; lugar ceremonial maya.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Laguna_Chicabal_04.jpg/500px-Laguna_Chicabal_04.jpg",null)
B.a0D=new A.c5("Cerro Quemado",14.7971,-91.5213,3197,"Quetzaltenango",!1,"Cerca de Xela; hizo erupci\xf3n en 1818. Buenas vistas de la ciudad.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Almolonga.jpg/500px-Almolonga.jpg",null)
B.a0A=new A.c5("Volc\xe1n Suchit\xe1n",14.3968,-89.7764,2046,"Jutiapa",!1,"Cono boscoso del oriente; caminata moderada.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Suchit%C3%A1n.jpg/500px-Suchit%C3%A1n.jpg",null)
B.a0p=new A.c5("Volc\xe1n de Chingo",14.118,-89.727,1775,"Jutiapa",!1,"En la frontera con El Salvador; la cima es compartida.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Chingo_volcano.jpg/500px-Chingo_volcano.jpg",null)
B.a0K=new A.c5("Volc\xe1n Ixtepeque",14.4248,-89.6835,1305,"Jutiapa",!1,"Famoso por su obsidiana, usada por los antiguos mayas.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Ixtepeque.jpg/500px-Ixtepeque.jpg",null)
B.a0r=new A.c5("Volc\xe1n Las V\xedboras",14.2113,-89.7267,1110,"Jutiapa",!1,"Peque\xf1o volc\xe1n del oriente seco; lleva mucha agua.",null,null,null)
B.a0q=new A.c5("Volc\xe1n Jumay",14.6941,-89.9924,2182,"Jalapa",!1,"S\xedmbolo de Jalapa; caminata popular entre la gente local.",null,null,null)
B.a0o=new A.c5("Volc\xe1n Tahual",14.4366,-89.9051,1722,"Jalapa",!1,"Cono del oriente con laguna cercana (Laguna de Retana).",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Tahual.jpg/500px-Tahual.jpg",null)
B.a0E=new A.c5("Volc\xe1n de Ipala",14.55,-89.63,1650,"Chiquimula",!1,"Tiene una laguna preciosa en el cr\xe1ter; caminata muy popular.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Laguna_de_Ipala%2C_Jutiapa.JPG/500px-Laguna_de_Ipala%2C_Jutiapa.JPG",null)
B.a0F=new A.c5("Volc\xe1n Tecuamburro",14.1561,-90.4069,1845,"Santa Rosa",!1,"Tiene fumarolas y la Laguna de Ixpaco (azufrada) en sus faldas.",null,"https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Laguna_de_Ixpaco%2C_Guatemala_por_Fabriccio_D%C3%ADaz.jpg/500px-Laguna_de_Ixpaco%2C_Guatemala_por_Fabriccio_D%C3%ADaz.jpg",null)
B.a0u=new A.c5("Volc\xe1n Siete Orejas",14.8148,-91.6177,3370,"Quetzaltenango",!1,"Cr\xe1ter en forma de herradura cerca de Xela; varias cumbres.",null,null,null)
